package stdlib

//go:generate go run ./gen

import (
	"strings"

	"github.com/phaenonlang/phaenon/internal/phpversion"
)

// Releases are the PHP releases whose library the embedded stubs describe,
// oldest first: the stubs are the newest one's, and the version table
// (versions_gen.go, generated by stdlib/gen from php-src's release
// branches) records what each newer one added to the oldest.
func Releases() []phpversion.Version { return append([]phpversion.Version(nil), releases...) }

// The lookups below answer "which release added this symbol?". They
// return false for a symbol every supported release has, and for a name
// the stubs do not declare at all. Names are fully qualified without the
// leading backslash; classes, functions and methods are matched without
// regard to case, constants and class constants exactly, as PHP does.

// FunctionSince returns the release that added a function.
func FunctionSince(name string) (phpversion.Version, bool) {
	return lookup("function " + strings.ToLower(name))
}

// ClassSince returns the release that added a class, interface, trait or
// enum.
func ClassSince(name string) (phpversion.Version, bool) {
	return lookup("class " + strings.ToLower(name))
}

// MethodSince returns the release that added a method to a class that
// exists in every supported release (a new class's methods come with it).
func MethodSince(class, method string) (phpversion.Version, bool) {
	return lookup("method " + strings.ToLower(class) + "::" + strings.ToLower(method))
}

// ConstantSince returns the release that added a global constant.
func ConstantSince(name string) (phpversion.Version, bool) {
	if i := strings.LastIndexByte(name, '\\'); i >= 0 {
		name = strings.ToLower(name[:i]) + name[i:]
	}
	return lookup("const " + name)
}

// ClassConstantSince returns the release that added a class constant or
// an enum case to a class that exists in every supported release.
func ClassConstantSince(class, name string) (phpversion.Version, bool) {
	return lookup("classconst " + strings.ToLower(class) + "::" + name)
}

// ParamSince returns the release that added a parameter to a function
// (callee "name") or a method (callee "Class::method") that exists in
// every supported release.
func ParamSince(callee, param string) (phpversion.Version, bool) {
	kind := "function "
	if strings.Contains(callee, "::") {
		kind = "method "
	}
	return lookup("param " + kind + strings.ToLower(callee) + " $" + param)
}

// DeprecatedIn returns the release whose stubs deprecated a symbol, for the
// deprecations added after the oldest supported release. key is spelled
// as the generated table spells it ("function is_double", "method
// splfileobject::fgetcsv").
func DeprecatedIn(key string) (phpversion.Version, bool) {
	v, ok := deprecatedIn[key]
	return v, ok
}

func lookup(key string) (phpversion.Version, bool) {
	v, ok := since[key]
	return v, ok
}
